    h, w = len(grid), len(grid[0])
    source = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not source or not marker:
        return out
    r0, r1 = min(r for r, c in source), max(r for r, c in source)
    c0, c1 = min(c for r, c in source), max(c for r, c in source)
    mr0, mr1 = min(r for r, c in marker), max(r for r, c in marker)
    mc0, mc1 = min(c for r, c in marker), max(c for r, c in marker)
    # A horizontally elongated marker calls for vertical reflection; a vertically
    # elongated marker calls for horizontal reflection. Reflect toward the marker.
    if (mc1 - mc0) >= (mr1 - mr0):
        down = sum(r for r, c in marker) / len(marker) > sum(r for r, c in source) / len(source)
        for r, c in source:
            rr = (2 * r1 + 1 - r) if down else (2 * r0 - 1 - r)
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        right = sum(c for r, c in marker) / len(marker) > sum(c for r, c in source) / len(source)
        for r, c in source:
            cc = (2 * c1 + 1 - c) if right else (2 * c0 - 1 - c)
            if 0 <= cc < w:
                out[r][cc] = 4
    for r, c in marker:
        out[r][c] = 0
    return out
